CREATE TABLE `application` (
  `id` int(10) UNSIGNED NOT NULL,
  `master` int(11) NOT NULL,
  `char_name` varchar(24) NOT NULL,
  `story` varchar(5000) NOT NULL,
  `ip_address` varchar(60) NOT NULL,
  `country_name` varchar(40) NOT NULL,
