--
-- Dumping data for table `application`
--

INSERT INTO `application` (`id`, `master`, `char_name`, `story`, `ip_address`, `country_name`, `country_code`, `status`, `reviewed_by`, `accepted`, `reason`, `date_of_submit`, `date_of_review`, `date_of_verdict`, `origin`, `gender`, `age`, `skin`) VALUES
(1, 1, 'Ganjar_Prabroro', 'Ganjar Prabroro adalah seorang pemuda berusia 24 tahun yang tinggal di desa kecil di lereng Gunung Merapi. Sejak kecil, Ganjar sudah memiliki kecintaan yang mendalam terhadap alam dan lingkungannya. Ia sering kali menghabiskan waktu di hutan sekitar desa, memerhatikan flora dan fauna serta mencatat semua yang ia pelajari dalam buku harian kecilnya.\n\nKehidupan Ganjar berubah saat ia menemukan seekor burung langka yang terluka di hutan. Dengan penuh kasih sayang, ia merawat burung tersebut hingga pulih. Pengalamannya ini membangkitkan minatnya untuk melindungi satwa liar yang terancam punah. Ganjar mulai aktif mengedukasi masyarakat sekitar tentang pentingnya pelestarian alam dan melakukan kampanye untuk menghentikan pemburuan ilegal.\n\nSemangat dan dedikasi Ganjar tidak hanya dihargai oleh warga desa, tetapi juga oleh organisasi lingkungan setempat. Ia mendapat kesempatan untuk bergabung dengan tim konservasi yang bergerak di wilayah tersebut. Dengan pengetahuannya yang luas dan semangatnya yang tak kenal lelah, Ganjar berhasil menjadikan desanya sebagai contoh dalam upaya pelestarian lingkungan.\n\nPada suatu hari, Ganjar menerima penghargaan dari pemerintah atas kontribusinya yang besar dalam melestarikan alam dan satwa liar. Penghargaan ini bukan hanya sebuah prestasi baginya, tetapi juga menjadi bukti bahwa kepeduliannya telah memberikan dampak yang positif bagi lingkungannya dan memberi inspirasi bagi banyak orang untuk ikut berperan dalam pelestarian alam.\n\nDengan setiap langkahnya, Ganjar Prabroro telah membuktikan bahwa satu individu dengan semangat dan tekad yang kuat dapat membuat perbedaan besar dalam menjaga keindahan alam yang kita miliki.', '127.0.0.1', 'Palembang', '30616', 1, 1, 1, 'Accepted', '0000-00-00 00:00:00', 'Monday', 'Pilat', 'Indonesia', 'Male', 30, 20261);

